    "faq.1.q": "Is it safe to process PDF files here?",
    "faq.1.a": "Absolutely. All files are processed locally in your web browser memory using high-performance WebAssembly modules. Not a single byte of your documents is ever uploaded or sent to our servers. Your sensitive business, personal, and confidential records stay entirely secure on your own device.",
    "faq.2.q": "Is TacoPDF truly 100% free?",
    "faq.2.a": "Yes, fully free with no hidden fees, no required account registrations, no forced watermarks, and no daily file limit caps. We display a small number of non-intrusive sponsor advertisements to help cover static hosting and custom domain overhead costs.",
    "faq.3.q": "Can I use this toolkit offline without internet?",
    "faq.3.a": "Yes! Once the web application is loaded in your browser for the first time, all PDF processing logic runs completely on the client side. You can safely disconnect your internet and continue to merge, split, rotate, or protect your PDF files fully offline.",
    "faq.4.q": "Why does this website show advertisements?",
