    "faq.5.q": "What file formats are supported?",
    "faq.5.a": "TacoPDF supports any standard PDF document (from version 1.0 to the newest standards), as well as popular image file formats like PNG, JPG, JPEG, and WebP to compile them into professional-grade PDF documents.",
