    "about.p1.title": "Born from Personal Frustration, Built to Help Everyone",
    "about.p1.text1": "Hello, my name is Muhammad Bayu Edi, a developer based in Central Java, Indonesia. The idea behind this platform stems from my own daily professional struggles and frustrations.",
    "about.p1.text2": "In my line of work, dealing with documents is a daily routine. However, finding a truly reliable online PDF tool felt incredibly difficult. Most services out there limit your file sizes, force intrusive watermarks, require account registrations, or worst of all—secretly upload your sensitive company documents to their servers.",
    "about.p1.text3": "Driven by this frustration, I decided to build my own document utility tool that is secure, fast, and dependable for everyone to use—without any annoying restrictions.",
    "about.p2.title": "Why the Name \"TacoPDF\"?",
    "about.p2.text1": "You might be wondering, why does a document app from Indonesia use the name of a Mexican dish? The story is quite simple. A while ago, while spending time in Jakarta, I had the chance to taste a Taco for the very first time and instantly fell in love with it. A taco is simple, practical, yet fully loaded and incredibly satisfying.",
    "about.p2.text2": "That is exactly the philosophy I brought into this website: I wanted TacoPDF to be simple and practical to use, yet fully loaded with features to satisfy all your document needs.",
    "about.p3.title": "Uncompromising Security (100% Offline Processing)",
    "about.p3.text1": "I firmly believe that productivity should never compromise data privacy. That is exactly why TacoPDF is engineered using cutting-edge WebAssembly (WASM) technology. Because of this innovation, all PDF modifications happen entirely inside your local browser.",
    "about.p3.text2": "Your files are never uploaded or stored by our servers. What happens on your device, stays strictly on your device.",
    "about.p4.title": "Our Free Service Commitment",
    "about.p4.text1": "TacoPDF is committed to providing professional document tools with no hidden subscription fees. To keep this website running 100% free and cover our server and hosting maintenance costs, we solely rely on displaying non-intrusive sponsor advertisements from trusted networks. Your support in using our platform means the world to us.",
    "about.p5.title": "Let's Connect",
    "about.p5.text1": "This platform was built to simplify everyday tasks for students, professionals, and businesses alike. If you have any feature suggestions, encounter bugs, or simply want to say hello, please feel free to reach out to me directly at mbayuedi@gmail.com.",
    "about.p5.text2": "Thank you for trusting TacoPDF with your documents!",
