    "contact.faq": "Pertanyaan yang Sering Diajukan (FAQ)",
    "contact.faq1_q": "Apakah file PDF saya disimpan oleh Tacopdf?",
    "contact.faq1_a": "Tidak. Semua pemrosesan (seperti memisahkan, menggabungkan, memberi watermark) dilakukan secara lokal di dalam browser Anda. File Anda tidak pernah diunggah ke server kami, menjamin privasi 100%.",
    "contact.faq2_q": "Apakah alat di Tacopdf benar-benar gratis?",
    "contact.faq2_a": "Ya, seluruh alat PDF yang kami sediakan gratis untuk digunakan. Kami menggunakan iklan non-intrusif (seperti untuk mendukung biaya operasional website ini.",

    "tool.redact.howto.1": "Unggah PDF yang berisi informasi sensitif.",
    "tool.redact.howto.2": "Gambar persegi panjang hitam di atas teks atau gambar yang ingin disensor.",
    "tool.redact.howto.3": "Klik 'Jalankan Sensor PDF' untuk menerapkan pemblokiran permanen.",
    "tool.redact.howto.4": "Unduh versi yang telah disensor secara aman.",
    "tool.redact.tips.1": "Setelah disensor, teks yang mendasarinya benar-benar dihapus dan tidak dapat dipulihkan.",
    "tool.redact.tips.2": "Selalu periksa kembali area sensor Anda di pratinjau sebelum menyimpan dokumen akhir.",
    "tool.redact.clear_page": "Hapus Halaman",
    "tool.redact.edit_page": "Edit Halaman",
    "tool.redact.done_edit": "Selesai Edit",
    "faq.1.q": "Apakah aman memproses file PDF di sini?",
    "faq.1.a": "Tentu saja. Semua file diproses secara lokal di memori browser Anda menggunakan modul WebAssembly berkinerja tinggi. Tidak ada satu byte pun dari dokumen Anda yang pernah diunggah atau dikirim ke server kami. Dokumen Anda tetap sepenuhnya aman di perangkat Anda sendiri.",
    "faq.2.q": "Apakah TacoPDF benar-benar 100% gratis?",
    "faq.2.a": "Ya, sepenuhnya gratis tanpa biaya tersembunyi, tanpa perlu mendaftar akun, tanpa watermark paksa, dan tanpa batasan jumlah file harian. Kami hanya menampilkan sedikit iklan sponsor untuk menutupi biaya server.",
    "faq.3.q": "Bisakah saya menggunakan alat ini offline tanpa internet?",
    "faq.3.a": "Bisa! Setelah aplikasi web dimuat di browser Anda untuk pertama kalinya, semua logika pemrosesan PDF berjalan sepenuhnya di sisi klien. Anda dapat memutuskan koneksi internet dengan aman dan melanjutkan proses secara offline penuh.",
    "faq.4.q": "Mengapa website ini menampilkan iklan?",
    "faq.4.a": "Sebagai alat utilitas publik yang mengutamakan keamanan tanpa membebankan biaya langganan, iklan sponsor membantu mendanai infrastruktur dasar kami. Kami menempatkan iklan agar tidak mengganggu, nyaman dilihat, dan terpisah dari ruang kerja aktif Anda.",
    "faq.5.q": "Format file apa saja yang didukung?",
    "faq.5.a": "TacoPDF mendukung dokumen PDF standar (dari versi 1.0 hingga standar terbaru), serta format file gambar populer seperti PNG, JPG, JPEG, dan WebP untuk diubah menjadi dokumen PDF.",
