    "about.p1.title": "Berawal dari Keresahan Pribadi, Hadir untuk Membantu Banyak Orang",
    "about.p1.text1": "Perkenalkan, nama saya Muhammad Bayu Edi, seorang pengembang perangkat lunak dari Jawa Tengah, Indonesia. Ide di balik berdirinya platform ini lahir dari pengalaman dan rasa frustrasi saya sendiri di dunia kerja.",
    "about.p1.text2": "Setiap hari, pekerjaan menuntut saya untuk mengurus banyak dokumen. Namun, menemukan alat PDF online yang benar-benar praktis rasanya sangat sulit. Mayoritas layanan membatasi ukuran file, menempelkan watermark secara paksa, mewajibkan pendaftaran akun, atau diam-diam mengunggah dokumen perusahaan ke server mereka.",
    "about.p1.text3": "Dari keresahan itulah, saya memutuskan untuk membangun alat utilitas dokumen sendiri yang aman, cepat, dan bisa diandalkan oleh siapa saja—tanpa batasan yang menjengkelkan.",
    "about.p2.title": "Mengapa Dinamakan \"TacoPDF\"?",
    "about.p2.text1": "Mungkin Anda bertanya-tanya, mengapa aplikasi dokumen dari Indonesia menggunakan nama makanan khas Meksiko? Beberapa waktu lalu saat di Jakarta, saya berkesempatan mencicipi Taco untuk pertama kalinya dan langsung jatuh cinta. Taco itu simpel, praktis, namun padat isian dan memuaskan.",
    "about.p2.text2": "Filosofi itulah yang saya bawa ke dalam website ini: Saya ingin TacoPDF menjadi alat yang tampilannya simpel dan praktis digunakan, namun memiliki fitur yang sangat padat dan memuaskan semua kebutuhan dokumen Anda.",
    "about.p3.title": "Teknologi Keamanan Tanpa Kompromi (100% Offline)",
    "about.p3.text1": "Bagi saya, produktivitas tidak boleh mengorbankan privasi data. Itulah mengapa TacoPDF dibangun menggunakan teknologi mutakhir WebAssembly (WASM). Berkat inovasi ini, seluruh proses modifikasi file terjadi sepenuhnya di dalam browser perangkat Anda.",
    "about.p3.text2": "File Anda tidak pernah sekalipun diunggah atau disimpan oleh server kami. Apa yang terjadi di perangkat Anda, tetap berada di perangkat Anda.",
    "about.p4.title": "Komitmen Layanan Gratis",
    "about.p4.text1": "TacoPDF berkomitmen menyediakan alat dokumen profesional tanpa biaya berlangganan tersembunyi. Untuk memastikan website ini tetap beroperasi secara gratis dan menutupi biaya operasional server, kami hanya menampilkan iklan sponsor dari jaringan mitra yang terpercaya. Dukungan Anda sangat berarti.",
    "about.p5.title": "Mari Terhubung",
    "about.p5.text1": "Platform ini dibangun untuk mempermudah pekerjaan sehari-hari, baik untuk kalangan pelajar, profesional, maupun instansi. Jika Anda memiliki saran fitur baru, menemukan bug, atau sekadar ingin menyapa, hubungi saya secara langsung melalui email di mbayuedi@gmail.com.",
    "about.p5.text2": "Terima kasih telah mempercayakan dokumen Anda pada TacoPDF!",
