    "tool.delete-pages.tip.title": "🗑️ BUANG YANG KOSONG",
    "tool.delete-pages.tip.desc": "Singkirkan halaman sampul yang tidak perlu atau halaman kosong di akhir dokumen agar file Anda terlihat lebih rapi dan profesional.",
    "tool.extract-pages.tip.title": "🎯 FOKUS KE INTI",
    "tool.extract-pages.tip.desc": "Berbeda dengan fitur hapus, fitur ini memudahkan Anda menyaring (filter) hanya halaman spesifik untuk dibuat menjadi PDF baru.",
    "tool.protect.tip.title": "🔒 ENKRIPSI STANDAR MILITER",
    "tool.protect.tip.desc": "Sandi Anda dikunci dengan standar algoritma kuat. Kami tidak menyimpan sandi ini, jadi pastikan Anda tidak melupakannya!",
    "tool.unlock.tip.title": "🔓 SEKALI BUKA",
