    "tool.sign.tip.title": "✍️ TANDA TANGAN WYSIWYG",
    "tool.sign.tip.desc": "Seret (drag) tanda tangan Anda secara presisi ke garis yang diinginkan. Apa yang Anda lihat di layar adalah apa yang akan Anda dapatkan!",
    "tool.redact.tip.title": "⬛ SENSOR PERMANEN",
    "tool.redact.tip.desc": "Kotak ini bukan sekadar stiker warna hitam! Ia menghapus data teks di baliknya secara permanen sehingga tidak bisa di-copy-paste lagi.",
    "tool.image-to-pdf.tip.title": "🖼️ GAMBAR KE PDF",
    "tool.image-to-pdf.tip.desc": "Unggah gambar JPG, PNG, atau WEBP — bisa banyak sekaligus! Seret kartu gambar untuk mengatur urutannya. Pilih ukuran halaman: A4, Letter, atau Sesuai Gambar.",
    "tool.pdf-to-image.tip.title": "🖼️ IDEAL UNTUK SOSMED",
    "tool.pdf-to-image.tip.desc": "File PDF tidak bisa diposting di feed Instagram/Facebook. Ubah ke JPG/PNG resolusi tinggi di sini agar bisa dibagikan dengan mudah!",
    "tool.html-to-pdf.tip.title": "🌐 INVOICE & RESI",
    "tool.html-to-pdf.tip.desc": "Sangat berguna untuk menyalin kode bon belanja atau artikel web mentah lalu mengubahnya menjadi dokumen PDF rapi siap cetak.",
