    "tool_name.extract_pages": "Ekstrak Halaman",
    "tool_name.add_page_numbers": "Nomor Halaman",
    "tool_name.html_to_pdf": "HTML ke PDF",
    "seo.header.title": "Kumpulan Alat PDF Gratis Terbaik Tanpa Unggah Server",
    "seo.header.subtitle": "TacoPDF: Editor PDF Berbasis Browser yang 100% Aman, Cepat & Privat",
    "seo.box1.title": "100% Pemrosesan Lokal",
    "seo.box1.desc": "Dokumen Anda tidak pernah dikirim melalui internet atau disimpan di server cloud. Semua proses pengeditan, penggabungan, dan enkripsi dieksekusi langsung di dalam browser web Anda menggunakan memori lokal.",
    "seo.box2.title": "Teknologi WebAssembly",
    "seo.box2.desc": "Ditenagai oleh mesin biner WebAssembly (Wasm) berkinerja tinggi, bahkan file PDF yang sangat besar diproses secara instan dalam hitungan milidetik. Tidak perlu waktu unggah atau unduh yang lambat.",
    "seo.box3.title": "Sepenuhnya Gratis & Offline",
    "seo.box3.desc": "Sepenuhnya gratis digunakan tanpa batasan penggunaan harian atau hambatan langganan berbayar. Cukup muat halaman sekali, dan Anda dapat terus memproses PDF Anda secara offline tanpa koneksi internet.",
    "seo.secure.title": "Optimasi Dokumen PDF yang Aman Tanpa Risiko Keamanan Apapun",
    "seo.secure.p1": "Dalam lanskap digital saat ini, dokumen PDF seringkali berisi data yang sangat sensitif seperti neraca keuangan, pindaian dokumen identitas pribadi (KTP, Paspor), kontrak hukum, dan catatan medis. Menggunakan konverter online biasa memaksa Anda untuk mempercayakan dokumen berharga Anda ke server cloud pihak ketiga, memaparkan Anda pada kerentanan pelanggaran data.",
    "seo.secure.p2": "<strong className=\"text-primary font-semibold\">TacoPDF</strong> menetapkan standar baru dalam manajemen file digital. Dengan mengkompilasi seluruh mesin pemrosesan secara lokal, kami menjamin bahwa file Anda tetap sepenuhnya di tangan Anda. Ini adalah cara paling aman dan privat untuk mengedit, memisahkan, menggabungkan, dan mengoptimalkan dokumen tanpa menyentuh internet.",
    "seo.features.title": "Fitur Luar Biasa yang Disesuaikan untuk Produktivitas Dokumen Anda",
    "seo.privacy.title": "Kebijakan Privasi",
    "seo.privacy.p1": "TacoPDF sangat berkomitmen untuk menghormati dan menjaga privasi pengguna. Karena semua fitur modifikasi dan konversi PDF dieksekusi secara eksklusif menggunakan WebAssembly dan JavaScript sisi klien, kami tidak pernah mengumpulkan, memantau, menyimpan, atau mentransmisikan isi dokumen Anda. File Anda tidak pernah menyentuh server kami.",
    "seo.privacy.p2": "<strong>Kebijakan Cookie & Iklan Pihak Ketiga:</strong> Kami menampilkan iklan sponsor yang tidak mengganggu melalui jaringan seperti untuk mengimbangi biaya operasional pemeliharaan hosting statis dan domain kustom kami. Jaringan iklan ini dapat menyebarkan cookie untuk mengumpulkan analitik non-personal (seperti alamat IP, jenis browser, dan preferensi minat iklan) untuk menyajikan rekomendasi iklan yang relevan.",
    "seo.privacy.p3": "Dengan menggunakan TacoPDF, Anda menyetujui model pemrosesan browser lokal dan pedoman cookie kami. Kami menjamin tidak ada tingkat premium yang tersembunyi, tidak ada pendaftaran akun yang dipaksakan, dan tidak ada tanda air (watermark) pada hasil Anda. Ini adalah utilitas publik yang sepenuhnya gratis yang dibangun untuk manajemen dokumen yang aman dan produktif.",
    "seo.features.merge": "Gabungkan beberapa lembar laporan atau slide menjadi satu dokumen PDF yang ringkas dengan mulus.",
    "seo.features.split": "Ekstrak halaman krusial tertentu untuk membuat dokumen PDF baru dalam sekejap.",
    "seo.features.rotate": "Perbaiki pindaian terbalik dengan memutar halaman tertentu persis seperti yang dibutuhkan.",
    "seo.features.protect": "Kunci dan enkripsi file PDF sensitif secara lokal menggunakan algoritma AES standar yang aman.",
    "seo.features.unlock": "Hapus kata sandi dari dokumen Anda sendiri untuk pencetakan dan berbagi yang lebih mudah.",
    "seo.features.redact": "Hitamkan dan sensor teks atau gambar sensitif secara permanen untuk melindungi informasi rahasia.",
    "seo.features.image_to_pdf": "Ubah gambar PNG, JPG, JPEG, dan WebP menjadi file PDF siap cetak resmi secara instan.",
    "seo.features.pdf_to_image": "Ekstrak dan render setiap halaman PDF Anda menjadi foto gambar berkualitas tinggi.",
    "seo.features.delete_pages": "Iris halaman kosong atau yang tidak diinginkan dari struktur dokumen Anda dengan bersih.",
    "seo.features.extract_pages": "Pilih hanya halaman yang ingin Anda simpan dan simpan sebagai file yang ringan.",
    "seo.features.add_watermark": "Amankan ID pindaian, tanda terima, atau draf dengan hamparan teks diagonal yang dapat disesuaikan sepenuhnya.",
    "seo.features.add_page_numbers": "Cap format penomoran kustom dan hitungan halaman dinamis dengan mulus ke halaman Anda.",
