    "about.p1.title": "Nacido de la frustración personal, creado para ayudar a todos",
    "about.p1.text1": "Hola, mi nombre es Muhammad Bayu Edi, un desarrollador con sede en Java Central, Indonesia. La idea detrás de esta plataforma surge de mis propias frustraciones y luchas profesionales diarias.",
    "about.p1.text2": "En mi línea de trabajo, tratar con documentos es una rutina diaria. Sin embargo, encontrar una herramienta PDF en línea verdaderamente confiable era increíblemente difícil. La mayoría de los servicios limitan el tamaño, fuerzan marcas de agua, requieren cuentas o, lo peor, suben sus documentos a sus servidores.",
    "about.p1.text3": "Impulsado por esta frustración, decidí crear mi propia herramienta que sea segura, rápida y confiable para todos, sin restricciones molestas.",
    "about.p2.title": "¿Por qué el nombre \"TacoPDF\"?",
    "about.p2.text1": "Se preguntará, ¿por qué una aplicación de Indonesia usa el nombre de un plato mexicano? Hace un tiempo, en Yakarta, tuve la oportunidad de probar un Taco por primera vez y me enamoré al instante. Un taco es simple, práctico, pero muy completo y satisfactorio.",
    "about.p2.text2": "Esa es exactamente la filosofía que traje a este sitio web: quería que TacoPDF fuera simple y práctico de usar, pero repleto de funciones para satisfacer sus necesidades.",
    "about.p3.title": "Seguridad sin concesiones (Procesamiento 100% sin conexión)",
    "about.p3.text1": "Creo firmemente que la productividad nunca debe comprometer la privacidad. Es por eso que TacoPDF utiliza tecnología WebAssembly (WASM). Gracias a esto, todas las modificaciones de PDF ocurren completamente dentro de su navegador local.",
    "about.p3.text2": "Sus archivos nunca se cargan ni se almacenan en nuestros servidores. Lo que sucede en su dispositivo, se queda estrictamente en su dispositivo.",
    "about.p4.title": "Nuestro compromiso de servicio gratuito",
    "about.p4.text1": "TacoPDF se compromete a proporcionar herramientas profesionales sin tarifas de suscripción ocultas. Para mantener este sitio 100% gratuito y cubrir nuestros costos de servidor, confiamos en mostrar anuncios de patrocinadores de redes confiables. Su apoyo significa el mundo para nosotros.",
    "about.p5.title": "Conectemos",
    "about.p5.text1": "Esta plataforma fue creada para simplificar las tareas diarias de estudiantes, profesionales y empresas. Si tiene sugerencias, encuentra errores o simplemente quiere saludar, comuníquese directamente conmigo en mbayuedi@gmail.com.",
    "about.p5.text2": "¡Gracias por confiar en TacoPDF con sus documentos!",
