    "about.p1.title": "個人的な不満から生まれ、すべての人を助けるために作られた",
    "about.p1.text1": "こんにちは、私の名前はムハマド バユ エディです。インドネシアの中部ジャワに拠点を置く開発者です。 このプラットフォームの背後にあるアイデアは、私自身の日々の職業上の葛藤と不満から生まれました。",
    "about.p1.text2": "私の仕事では書類を扱うのが日課です。 しかし、本当に信頼できるオンライン PDF ツールを見つけるのは非常に難しいと感じました。 世の中のサービスのほとんどは、ファイル サイズを制限したり、侵入的な透かしを強制したり、アカウント登録を要求したり、最悪の場合、会社の機密文書をサーバーに秘密裏にアップロードしたりします。",
    "about.p1.text3": "このフラストレーションに駆られて、私は煩わしい制限なしで誰もが使用できる、安全で高速で信頼性の高い独自のドキュメント ユーティリティ ツールを構築することにしました。",
    "about.p2.title": "なぜ「TacoPDF」という名前なのでしょうか?",
    "about.p2.text1": "なぜインドネシアのドキュメント アプリがメキシコ料理の名前を使用しているのか疑問に思われるかもしれません。 話はとてもシンプルです。 少し前、ジャカルタで時間を過ごしたときに、初めてタコスを味わう機会があり、すぐにタコスの虜になりました。 タコスはシンプルで実用的ですが、ボリュームたっぷりで信じられないほど満足感があります。",
    "about.p2.text2": "それがまさに私がこの Web サイトに持ち込んだ哲学です。TacoPDF がシンプルで実用的でありながら、ドキュメントのすべてのニーズを満たす機能が満載であることを望んでいました。",
    "about.p3.title": "妥協のないセキュリティ (100% オフライン処理)",
    "about.p3.text1": "私は、生産性向上のためにデータ プライバシーを決して侵害すべきではないと強く信じています。 まさにそれが、TacoPDF が最先端の WebAssembly (WASM) テクノロジーを使用して設計されている理由です。 この革新により、PDF の変更はすべてローカル ブラウザ内で完全に行われます。",
    "about.p3.text2": "あなたのファイルが当社のサーバーによってアップロードまたは保存されることはありません。 デバイス上で起こったことは、厳密にデバイス上に残ります。",
    "about.p4.title": "無料サービスへの取り組み",
    "about.p4.text1": "TacoPDF は、隠れたサブスクリプション料金なしでプロフェッショナルなドキュメント ツールを提供することに尽力しています。 このウェブサイトを完全に無料で運営し続け、サーバーとホスティングのメンテナンス費用をカバーするために、当社は信頼できるネットワークからの非侵入的なスポンサー広告の表示のみに依存しています。 私たちのプラットフォームを使用する際のあなたのサポートは、私たちにとって世界を意味します。",
    "about.p5.title": "つながろう",
    "about.p5.text1": "このプラットフォームは、学生、専門家、企業などの日常業務を簡素化するために構築されました。 機能に関するご提案がある場合、バグに遭遇した場合、または単にご挨拶したい場合は、お気軽に mbayuedi@gmail.com まで直接ご連絡ください。",
    "about.p5.text2": "ドキュメントに関して TacoPDF を信頼していただきありがとうございます。",
