    "about.p1.title": "Nascido da frustração pessoal, criado para ajudar a todos",
    "about.p1.text1": "Olá, meu nome é Muhammad Bayu Edi, desenvolvedor baseado em Java Central, Indonésia. A ideia por trás desta plataforma deriva de minhas próprias lutas e frustrações profissionais diárias.",
    "about.p1.text2": "No meu ramo de trabalho, lidar com documentos é uma rotina diária. No entanto, encontrar uma ferramenta PDF online verdadeiramente confiável pareceu incrivelmente difícil. A maioria dos serviços disponíveis limita o tamanho dos arquivos, força marcas d'água intrusivas, exige registros de contas ou, o pior de tudo, carrega secretamente os documentos confidenciais da empresa em seus servidores.",
    "about.p1.text3": "Impulsionado por essa frustração, decidi criar minha própria ferramenta utilitária de documentos que seja segura, rápida e confiável para uso de todos, sem quaisquer restrições irritantes.",
    "about.p2.title": "Por que o nome \"TacoPDF\"?",
    "about.p2.text1": "Você deve estar se perguntando: por que um aplicativo de documentos da Indonésia usa o nome de um prato mexicano? A história é bastante simples. Há algum tempo, durante uma passagem por Jacarta, tive a oportunidade de provar um Taco pela primeira vez e me apaixonei instantaneamente por ele. Um taco é simples, prático, mas totalmente carregado e incrivelmente satisfatório.",
    "about.p2.text2": "Essa é exatamente a filosofia que trouxe para este site: eu queria que o TacoPDF fosse simples e prático de usar, mas totalmente carregado com recursos para satisfazer todas as suas necessidades documentais.",
    "about.p3.title": "Segurança intransigente (processamento 100% offline)",
    "about.p3.text1": "Acredito firmemente que a produtividade nunca deve comprometer a privacidade dos dados. É exatamente por isso que o TacoPDF foi projetado usando tecnologia de ponta WebAssembly (WASM). Devido a esta inovação, todas as modificações do PDF acontecem inteiramente dentro do seu navegador local.",
    "about.p3.text2": "Seus arquivos nunca são carregados ou armazenados em nossos servidores. O que acontece no seu dispositivo permanece estritamente no seu dispositivo.",
    "about.p4.title": "Nosso compromisso de serviço gratuito",
    "about.p4.text1": "TacoPDF está empenhada em fornecer ferramentas de documentos profissionais sem taxas de assinatura ocultas. Para manter este site funcionando 100% gratuito e cobrir nossos custos de manutenção de servidor e hospedagem, contamos exclusivamente com a exibição de anúncios de patrocinadores não intrusivos de redes confiáveis. Seu apoio no uso de nossa plataforma significa muito para nós.",
    "about.p5.title": "Vamos nos conectar",
    "about.p5.text1": "Esta plataforma foi construída para simplificar as tarefas diárias de estudantes, profissionais e empresas. Se você tiver alguma sugestão de recurso, encontrar bugs ou simplesmente quiser dizer olá, sinta-se à vontade para entrar em contato comigo diretamente em mbayuedi@gmail.com.",
    "about.p5.text2": "Obrigado por confiar seus documentos à TacoPDF!",
