    "tool.sign.tip.desc": "Arraste sua assinatura precisamente para a linha desejada. O que você vê na tela é o que você obtém!",
    "tool.redact.tip.title": "⬛ CENSOR PERMANENTE",
    "tool.redact.tip.desc": "Esta caixa não é apenas um adesivo preto! Ele remove permanentemente os dados de texto por trás dele para que não possam mais ser copiados e colados.",
    "tool.image-to-pdf.tip.title": "🖼️ IMAGEM PARA PDF",
    "tool.image-to-pdf.tip.desc": "Faça upload de imagens JPG, PNG ou WEBP – várias de uma vez! Arraste os cartões para reordená-los antes de converter. Escolha o tamanho da página: A4, Carta ou Ajustar à imagem.",
    "tool.pdf-to-image.tip.title": "🖼️ IDEAL PARA REDES SOCIAIS",
    "tool.pdf-to-image.tip.desc": "Arquivos PDF não podem ser postados em feeds sociais. Converta para JPG/PNG de alta resolução aqui para que possam ser facilmente compartilhados!",
