    "about.p1.title": "Né d'une frustration personnelle, conçu pour aider tout le monde",
    "about.p1.text1": "Bonjour, je m'appelle Muhammad Bayu Edi, un développeur basé dans le centre de Java, en Indonésie. L'idée derrière cette plateforme découle de mes propres luttes et frustrations professionnelles quotidiennes.",
    "about.p1.text2": "Dans mon domaine de travail, traiter des documents est une routine quotidienne. Cependant, trouver un outil PDF en ligne vraiment fiable s'est avéré incroyablement difficile. La plupart des services limitent la taille de vos fichiers, imposent des filigranes intrusifs ou téléchargent secrètement vos documents sur leurs serveurs.",
    "about.p1.text3": "Poussé par cette frustration, j'ai décidé de créer mon propre outil utilitaire de documents sécurisé, rapide et fiable pour tout le monde.",
    "about.p2.title": "Pourquoi le nom \"TacoPDF\" ?",
    "about.p2.text1": "Vous vous demandez peut-être pourquoi une application indonésienne utilise le nom d'un plat mexicain ? L'histoire est assez simple. Il y a quelque temps, à Jakarta, j'ai eu la chance de goûter un taco pour la toute première fois et j'en suis instantanément tombé amoureux. Un taco est simple, pratique, mais très complet et incroyablement satisfaisant.",
    "about.p2.text2": "C'est exactement la philosophie que j'ai apportée à ce site Web : je voulais que TacoPDF soit simple et pratique à utiliser, mais doté de nombreuses fonctionnalités pour satisfaire tous vos besoins en matière de documents.",
    "about.p3.title": "Sécurité sans compromis (Traitement 100% hors ligne)",
    "about.p3.text1": "Je crois fermement que la productivité ne doit jamais compromettre la confidentialité des données. C'est pourquoi TacoPDF est conçu à l'aide de la technologie de pointe WebAssembly (WASM). Grâce à cela, toutes les modifications PDF s'effectuent entièrement dans votre navigateur local.",
    "about.p3.text2": "Vos fichiers ne sont jamais téléchargés ou stockés par nos serveurs. Ce qui se passe sur votre appareil reste strictement sur votre appareil.",
    "about.p4.title": "Notre engagement de service gratuit",
    "about.p4.text1": "TacoPDF s'engage à fournir des outils documentaires professionnels sans frais d'abonnement cachés. Pour que ce site Web reste 100 % gratuit et pour couvrir nos coûts de serveur, nous comptons uniquement sur l'affichage de publicités de sponsors.",
    "about.p5.title": "Connectons-nous",
    "about.p5.text1": "Cette plateforme a été conçue pour simplifier les tâches quotidiennes des étudiants, des professionnels et des entreprises. Si vous avez des suggestions, rencontrez des bugs ou voulez dire bonjour, n'hésitez pas à me contacter directement à mbayuedi@gmail.com.",
    "about.p5.text2": "Merci de confier vos documents à TacoPDF !",
