    "workspace.preview.blank.title": "L'aperçu PDF est-il vide ou affiche-t-il une page bloquée ?",
    "workspace.preview.blank.desc": "Ne vous inquiétez pas ! Il s'agit d'une restriction de sécurité standard appliquée par les navigateurs Web modernes lors du rendu d'actifs PDF {blob} à l'intérieur d'iframes de développeur imbriquées.",
