    "tool.sign.editor_desc": "Faites défiler votre document ci-dessous. Cliquez sur \"Add Signature\" sur n'importe quelle page pour déposer votre signature. Faites-la glisser vers la position souhaitée.",
    "tool.merge.tip.title": "🌟 SUPER FUSION",
    "tool.merge.tip.desc": "Vous pouvez télécharger des dizaines de documents à la fois. N'oubliez pas de faire glisser les boîtes de fichiers sur la gauche pour organiser l'ordre avant le traitement !",
    "tool.split.tip.title": "💡 ASTUCE PETIT FICHIER",
    "tool.split.tip.desc": "Vous n'avez besoin que de quelques pages d'un PDF de plusieurs centaines de pages ? Les extraire ici rendra le fichier beaucoup plus léger à partager.",
    "tool.rotate.tip.title": "🔄 CORRECTION RAPIDE",
    "tool.rotate.tip.desc": "Obtenez-vous souvent des pages à l'envers suite à des erreurs de scanner ? Cliquez sur les pages sur l'écran de gauche pour les faire pivoter en quelques secondes !",
    "tool.delete-pages.tip.title": "🗑️ SUPPRIMER LES VIDES",
    "tool.delete-pages.tip.desc": "Débarrassez-vous des pages de couverture inutiles ou des pages vierges à la fin du document pour rendre votre fichier plus net et plus professionnel.",
    "tool.extract-pages.tip.title": "🎯 FOCUS SUR LE CŒUR",
    "tool.extract-pages.tip.desc": "Contrairement à la fonction de suppression, celle-ci vous permet de filtrer et de choisir uniquement des pages spécifiques pour créer un tout nouveau PDF.",
    "tool.protect.tip.title": "🔒 CHIFFREMENT MILITAIRE",
    "tool.protect.tip.desc": "Votre mot de passe est verrouillé avec une norme d'algorithme forte. Nous ne stockons pas ce mot de passe, assurez-vous donc de ne pas l'oublier !",
    "tool.unlock.tip.title": "🔓 DÉVERROUILLER UNE FOIS",
    "tool.unlock.tip.desc": "Supprimez la couche de chiffrement de votre document pour ne pas avoir à retaper le mot de passe à chaque fois que vous ouvrez le fichier.",
    "tool.sign.tip.title": "✍️ SIGNATURE WYSIWYG",
    "tool.sign.tip.desc": "Faites glisser votre signature précisément sur la ligne souhaitée. Ce que vous voyez à l'écran est ce que vous obtenez !",
    "tool.redact.tip.title": "⬛ CENSURE PERMANENTE",
    "tool.redact.tip.desc": "Cette boîte n'est pas seulement un autocollant noir ! Elle supprime définitivement les données textuelles derrière elle afin qu'elles ne puissent plus être copiées-collées.",
    "tool.image-to-pdf.tip.title": "🖼️ IMAGE EN PDF",
    "tool.image-to-pdf.tip.desc": "Importez des images JPG, PNG ou WEBP — plusieurs à la fois ! Glissez les cartes pour les réorganiser avant la conversion. Choisissez la taille de page : A4, Letter ou Ajuster à l'image.",
    "tool.pdf-to-image.tip.title": "🖼️ IDÉAL POUR LES RÉSEAUX SOCIAUX",
    "tool.pdf-to-image.tip.desc": "Les fichiers PDF ne peuvent pas être publiés sur les flux sociaux. Convertissez en JPG/PNG haute résolution ici pour qu'ils puissent être facilement partagés !",
    "tool.html-to-pdf.tip.title": "🌐 FACTURES ET REÇUS",
    "tool.html-to-pdf.tip.desc": "Très utile pour coller du code de reçu brut ou des articles Web et les transformer en documents PDF soignés et prêts à imprimer.",
    "tool.add-watermark.tip.title": "©️ PROTÉGEZ VOTRE TRAVAIL",
    "tool.add-watermark.tip.desc": "Utilisez un faible niveau de transparence (opacité) afin que le tampon de droit d'auteur protège le document sans interrompre le contenu textuel d'origine.",
    "tool.add-page-numbers.tip.title": "🔢 NORME OFFICIELLE",
    "tool.add-page-numbers.tip.desc": "La plupart des institutions et universités exigent des numéros de page dans des coins spécifiques des documents. Faites-le en un clic ici !",
    "tool.merge.title": "Fusionner PDF",
    "tool.merge.howto.1": "Téléchargez deux fichiers PDF ou plus dans la zone de dépôt.",
    "tool.merge.howto.2": "Faites glisser et déposez les miniatures des fichiers pour organiser leur ordre de fusion.",
    "tool.merge.howto.3": "Cliquez sur le bouton 'Exécuter Fusionner PDF' pour combiner des fichiers localement dans votre navigateur.",
    "tool.merge.tips.1": "Vous pouvez réorganiser visuellement vos fichiers à tout moment avant de les fusionner.",
    "tool.split.title": "Diviser PDF",
    "tool.split.desc": "Extrayez des plages de pages spécifiques ou divisez un PDF en fichiers séparés.",
    "tool.split.howto.1": "Téléchargez le document PDF que vous souhaitez diviser.",
