    "seo.privacy.p2": "<strong>Politique relative aux cookies et à la publicité :</strong> Nous affichons des publicités non intrusives via pour compenser les coûts.",
    "seo.privacy.p3": "Nous garantissons aucun frais caché, aucune inscription forcée et aucun filigrane. Un utilitaire entièrement gratuit.",
